use prusti_contracts::*;

// Function: solve
// Input: queries - a vector of i8 integers
// Output: a vector of i8 integers with the same length as queries
// For each element n in queries:
//   If n >= 4, output n % 2
//   Otherwise, output 4 - n

#[requires(forall(|&n: &i8| n >= -128 && n <= 127))] // all i8 values are in range
#[ensures(result.len() == queries.len())]
#[ensures(forall(|i: usize| i < queries.len() ==> (
    if queries[i] >= 4 { result[i] == queries[i] % 2 } else { result[i] == 4 - queries[i] }
)))]
fn solve(queries: Vec<i8>) -> Vec<i8> {
    queries
        .into_iter()
        .map(|n| {
            if n >= 4 {
                n % 2
            } else {
                4 - n
            }
        })
        .collect()
}